use serde::{Deserialize, Serialize};

/// macOS platform configuration
#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(default)]
pub struct MacOSBuildConfig {
    /// Whether to build for macOS
    #[serde(default = "super::default_enabled")]
    pub enabled: bool,

    /// Bundle identifier for macOS application
    ///
    /// If not specified, the bundle identifier will
    /// use the app identifier generated by Flutter.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bundle_identifier: Option<String>,

    /// Minimum macOS system version supported by the application
    ///
    /// Default is "10.14".
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub minimum_system_version: Option<String>,

    /// macOS application category
    ///
    /// Default is "public.app-category.entertainment".
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,

    /// macOS DMG background image
    ///
    /// Default is None.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub dmg_background: Option<String>,

    /// macOS DMG window size
    ///
    /// Default is (500, 350).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub dmg_window_size: Option<(u32, u32)>,

    /// macOS codesign identity
    ///
    /// Default is None.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub codesign_identity: Option<String>,

    /// Entitlements applied when the bundle is signed
    ///
    /// Default is None, which means the file Flutter generated for the build
    /// mode is used (`macos/Runner/Release.entitlements`, or
    /// `DebugProfile.entitlements` for debug and profile builds). Relative
    /// paths are resolved against the project root.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub codesign_entitlements: Option<String>,

    /// macOS notarize credentials
    ///
    /// Default is None.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notarize_credentials: Option<String>,
}

impl Default for MacOSBuildConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            bundle_identifier: None,
            minimum_system_version: Some("10.14".to_string()),
            category: Some("public.app-category.entertainment".to_string()),
            dmg_background: None,
            dmg_window_size: Some((500, 350)),
            codesign_identity: None,
            codesign_entitlements: None,
            notarize_credentials: None,
        }
    }
}
